  "بر اساس الگوهای رایج فروشگاه‌های ایرانی، این چهار اقدام بیشترین اثر را دارند: ۱. **شفاف‌سازی ارزش پیشنهادی** در همان اسکرول اول (سرفصل + یک جمله + تصویر محصول). ۲. **کاهش گام‌های پرداخت**: هر گام اضافی حدود ۷٪ ریزش ایجاد می‌کند. ۳. **افزودن نشانه‌های اعتماد**: درگاه امن، ضمانت بازگشت، نظرات تأییدشده. ۴. **نمایش موجودی و زمان ارسال** روی کارت محصول؛ در دسته‌های حساس مثل دیجیتال، اثر آن دو برابر است.": "Based on common patterns in online stores, these four actions have the biggest impact: 1. **Clarify the value proposition** in the very first scroll (headline + one sentence + product image). 2. **Reduce checkout steps**: every extra step causes about 7% drop-off. 3. **Add trust signals**: secure gateway, money-back guarantee, verified reviews. 4. **Show stock and delivery time** on the product card; in sensitive categories such as electronics the effect doubles.",
