  "گزارش عملکرد": "Performance report",
  "گزارش عملکرد فصل سوم شرکت نشان می‌دهد درآمد کل با رشد ۱۴.۲ درصدی نسبت به فصل قبل به ۲۲.۴ میلیارد ریال رسیده است. بیشترین سهم رشد مربوط به فروش آنلاین و مشتریان سازمانی بوده است. در همین دوره هزینه‌های عملیاتی ۴.۶ درصد افزایش یافت که عمدتاً ناشی از توسعه تیم پشتیبانی و راه‌اندازی مرکز تماس جدید بود. نرخ ریزش مشتریان سازمانی از ۳.۱ درصد به ۲.۴ درصد کاهش یافت و رضایت مشتریان در نظرسنجی فصلی به ۸۷ درصد رسید. با این حال سه ریسک اصلی شناسایی شده است: تأخیر در تأمین سرورهای جدید، وابستگی به یک درگاه پرداخت و کمبود نیروی متخصص داده. هیئت مدیره پیشنهاد کرده است بودجه فصل آینده با تمرکز بر تنوع درگاه‌های پرداخت و جذب تحلیلگر داده بازنگری شود.": "The company's Q3 performance report shows total revenue grew 14.2% quarter over quarter to 22.4 billion IRR. Most of the growth came from online sales and enterprise customers. Over the same period operating expenses rose 4.6%, mainly due to expanding the support team and opening a new call center. Enterprise churn fell from 3.1% to 2.4% and customer satisfaction reached 87% in the quarterly survey. However, three key risks were identified: delays in supplying new servers, dependence on a single payment gateway and a shortage of data specialists. The board has proposed revising next quarter's budget with a focus on diversifying payment gateways and hiring data analysts.",
